module case_example1(input logic [1:0] a, output logic y);
    always_comb begin
        case(a)
            2'b00: y = 0;
            2'b01: y = 1;
            2'b10: y = 1;
            2'b11: y = 0;
            default: y = 0;
        endcase
    end
endmodule,"

module ff_case_7(input logic clk, rst, stall, output logic [1:0] state);
always_ff @(posedge clk or posedge rst) begin
  if (rst) state <= 2'b00;
  else begin
    case(state)
      2'b00: state <= stall ? 2'b00 : 2'b01;
      2'b01: state <= stall ? 2'b01 : 2'b10;
      2'b10: state <= 2'b00;
      default: state <= 2'b00;
    endcase
  end
end
endmodule
,"

module instr_decoder (
    input  logic [31:0] instr,
    output logic        is_branch,
    output logic        is_load,
    output logic        is_store,
    output logic        illegal
);

    logic [6:0] opcode;
    logic [2:0] funct3;
    logic [6:0] funct7;

    assign opcode = instr[6:0];
    assign funct3 = instr[14:12];
    assign funct7 = instr[31:25];

    always_comb begin
        is_branch = 1'b0;
        is_load   = 1'b0;
        is_store  = 1'b0;
        illegal   = 1'b0;

        unique case (opcode)
            7'b1100011: begin // BRANCH
                is_branch = 1'b1;
                unique case (funct3)
                    3'b000, // BEQ
                    3'b001, // BNE
                    3'b100, // BLT
                    3'b101, // BGE
                    3'b110, // BLTU
                    3'b111: ; // BGEU
                    default: illegal = 1'b1;
                endcase
            end

            7'b0000011: begin // LOAD
                is_load = 1'b1;
                unique case (funct3)
                    3'b000, // LB
                    3'b001, // LH
                    3'b010, // LW
                    3'b100, // LBU
                    3'b101: ; // LHU
                    default: illegal = 1'b1;
                endcase
            end

            7'b0100011: begin // STORE
                is_store = 1'b1;
                unique case (funct3)
                    3'b000, // SB
                    3'b001, // SH
                    3'b010: ; // SW
                    default: illegal = 1'b1;
                endcase
            end

            default: illegal = 1'b1;
        endcase
    end

endmodule
,"

module dma_channel_arbiter (
    input  logic [3:0] ch_req,
    output logic [1:0] grant,
    output logic       grant_valid
);

    always_comb begin
        grant       = 2'd0;
        grant_valid = 1'b0;

        priority case (1'b1)
            ch_req[0]: begin
                grant       = 2'd0;
                grant_valid = 1'b1;
            end
            ch_req[1]: begin
                grant       = 2'd1;
                grant_valid = 1'b1;
            end
            ch_req[2]: begin
                grant       = 2'd2;
                grant_valid = 1'b1;
            end
            ch_req[3]: begin
                grant       = 2'd3;
                grant_valid = 1'b1;
            end
            default: begin
                grant_valid = 1'b0;
            end
        endcase
    end

endmodule
,"

module packet_classifier (
    input  logic [31:0] hdr,
    output logic        fast_path,
    output logic        slow_path,
    output logic        drop
);

    logic [7:0] proto;
    logic [3:0] subtype;
    logic [2:0] qos;

    assign proto   = hdr[31:24];
    assign subtype = hdr[23:20];
    assign qos     = hdr[2:0];

    always_comb begin
        fast_path = 1'b0;
        slow_path = 1'b0;
        drop      = 1'b0;

        unique case (proto)
            8'h08: begin // IPv4
                case (subtype)
                    4'h0: begin // UDP
                        case (qos)
                            3'b000, 3'b001: fast_path = 1'b1;
                            3'b111: drop = 1'b1;
                            default: slow_path = 1'b1;
                        endcase
                    end

                    4'h1: begin // TCP
                        case (qos)
                            3'b000: fast_path = 1'b1;
                            default: slow_path = 1'b1;
                        endcase
                    end

                    default: slow_path = 1'b1;
                endcase
            end

            8'h86: begin // IPv6
                case (subtype)
                    4'h0, 4'h1: slow_path = 1'b1;
                    default: drop = 1'b1;
                endcase
            end

            default: drop = 1'b1;
        endcase
    end

endmodule
,"

module storage_cmd_proc (
    input  logic [7:0] cmd,
    input  logic [3:0] feature,
    input  logic [1:0] subop,
    output logic       exec,
    output logic       flush,
    output logic       error
);

    always_comb begin
        exec  = 1'b0;
        flush = 1'b0;
        error = 1'b0;

        unique case (cmd)
            8'h01: begin // READ
                case (feature)
                    4'h0, 4'h1: exec = 1'b1;
                    4'hF: begin
                        case (subop)
                            2'b00: exec = 1'b1;
                            default: error = 1'b1;
                        endcase
                    end
                    default: error = 1'b1;
                endcase
            end

            8'h02: begin // WRITE
                case (feature)
                    4'h0: exec = 1'b1;
                    4'hE: flush = 1'b1;
                    default: error = 1'b1;
                endcase
            end

            8'hFF: begin // FLUSH
                flush = 1'b1;
            end

            default: error = 1'b1;
        endcase
    end

endmodule
,"

module obi_host_resp_gen (
    input  logic [1:0] obi_result_i,
    input  logic       obi_priv_i,
    output logic [1:0] obi_resp_o
);

    always_comb begin
        obi_resp_o = 2'b00;

        unique case (obi_result_i)
            2'b00: obi_resp_o = 2'b00; // OK

            2'b01: begin // Decode error
                case (obi_priv_i)
                    1'b1: obi_resp_o = 2'b10;
                    default: obi_resp_o = 2'b11;
                endcase
            end

            2'b10: begin // Access error
                case (obi_priv_i)
                    1'b1: obi_resp_o = 2'b11;
                    default: obi_resp_o = 2'b10;
                endcase
            end

            default: obi_resp_o = 2'b11;
        endcase
    end

endmodule
,"

module chisel_event_dispatch (
    input  logic [7:0] evt_i,
    input  logic [3:0] fsm_state_i,
    output logic       fire_o,
    output logic       stall_o,
    output logic       error_o
);

    always_comb begin
        fire_o  = 1'b0;
        stall_o = 1'b0;
        error_o = 1'b0;

        unique case (fsm_state_i)
            4'd0: begin
                unique case (evt_i[1:0])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd1: begin
                unique case (evt_i[3:2])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd2: begin
                unique case (evt_i[5:4])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            4'd3: begin
                unique case (evt_i[7:6])
                    2'b00: fire_o = 1'b1;
                    2'b01: stall_o = 1'b1;
                    default: error_o = 1'b1;
                endcase
            end

            default: error_o = 1'b1;
        endcase
    end
endmodule
,"

module multi_core_bus_arb (
    input  logic [3:0] req_i,
    input  logic [1:0] line_state_i [3:0],
    input  logic [2:0] msg_type_i [3:0],
    input  logic priv_i [3:0],
    output logic [3:0] grant_o,
    output logic [3:0] nack_o
);

    always_comb begin
        grant_o = 4'b0000;
        nack_o  = 4'b0000;

        for (int i=0; i<4; i++) begin
            if (req_i[i]) begin
                unique case (line_state_i[i])
                    2'b00: begin
                        unique case (msg_type_i[i])
                            3'b000: begin
                                unique case (priv_i[i])
                                    1'b1: grant_o[i] = 1'b1;
                                    default: nack_o[i] = 1'b1;
                                endcase
                            end
                            3'b001: grant_o[i] = 1'b1;
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b01: begin
                        unique case (msg_type_i[i])
                            3'b010: grant_o[i] = 1'b1;
                            default: nack_o[i] = 1'b1;
                        endcase
                    end
                    2'b10, 2'b11: nack_o[i] = 1'b1;
                    default: nack_o[i] = 1'b1;
                endcase
            end
        end
    end
endmodule
,"

module axi_tl_bridge_fsm (
    input  logic axi_awvalid_i,
    input  logic axi_arvalid_i,
    input  logic tl_ready_i,
    input  logic [2:0] tl_opcode_i,
    output logic tl_valid_o,
    output logic [2:0] tl_a_opcode_o,
    output logic error_o
);

    always_comb begin
        tl_valid_o = 1'b0;
        tl_a_opcode_o = 3'b000;
        error_o = 1'b0;

        if (axi_awvalid_i) begin
            tl_valid_o = tl_ready_i;
            tl_a_opcode_o = 3'b001;
        end else if (axi_arvalid_i) begin
            tl_valid_o = tl_ready_i;
            tl_a_opcode_o = 3'b000;
        end else begin
            error_o = 1'b1;
        end
    end
endmodule
,"

module chisel_prio_mux_masked (
    input  logic [3:0] sel_i,
    input  logic [7:0] in0_i, in1_i, in2_i, in3_i,
    input  logic mask_i,
    output logic [7:0] out_o
);

    always_comb begin
        out_o = 8'h00;

        case (1'b1)
            sel_i[0]: out_o = mask_i ? 8'h00 : in0_i;
            sel_i[1]: out_o = mask_i ? 8'h00 : in1_i;
            sel_i[2]: out_o = mask_i ? 8'h00 : in2_i;
            sel_i[3]: out_o = mask_i ? 8'h00 : in3_i;
            default: out_o = 8'h00;
        endcase
    end
endmodule
